const upsertManagerServer = `-- name: UpsertManagerServer :one
INSERT INTO manager_servers (id, name, provider, monthly_cents, notes)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name, provider = EXCLUDED.provider,
    monthly_cents = EXCLUDED.monthly_cents, notes = EXCLUDED.notes
RETURNING id, name, provider, monthly_cents, notes, active, created_at
`

type UpsertManagerServerParams struct {
	ID           uuid.UUID `json:"id"`
	Name         string    `json:"name"`
	Provider     string    `json:"provider"`
	MonthlyCents int32     `json:"monthly_cents"`
	Notes        string    `json:"notes"`
}

func (q *Queries) UpsertManagerServer(ctx context.Context, arg UpsertManagerServerParams) (ManagerServer, error) {
	row := q.db.QueryRow(ctx, upsertManagerServer,
		arg.ID,
		arg.Name,
		arg.Provider,
		arg.MonthlyCents,
		arg.Notes,
	)
	var i ManagerServer
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Provider,
		&i.MonthlyCents,
		&i.Notes,
		&i.Active,
		&i.CreatedAt,
	)
	return i, err
}

